interface Participant { send(message: string): void; receive(message: string): void; }

class Coordinator {
  participants: Participant[] = [];
  register(p: Participant) { this.participants.push(p); }
  send(sender: Participant, message: string) { this.participants.forEach(p => { if (p !== sender) p.receive(message); }); }
}

class ServiceA implements Participant {
  constructor(private coord: Coordinator) {}
  send(message: string) { this.coord.send(this, message); }
  receive(message: string) { console.log('A got', message); }
}

class ServiceB implements Participant {
  constructor(private coord: Coordinator) {}
  send(message: string) { this.coord.send(this, message); }
  receive(message: string) { console.log('B got', message); }
